// M9 - Lectura 3: la trazabilidad empieza ACA.
// n8n le da un executionId distinto a cada sub-workflow. Si no generamos un
// identificador propio y lo propagamos a mano, despues es imposible reconstruir
// la cadena de eventos: quedan tres ejecuciones huerfanas que nadie puede unir.

const entrada = $input.first().json;
const cuerpo = entrada.body ?? entrada;
const ahora = new Date();
const azar = Math.random().toString(36).slice(2, 8).toUpperCase();

return [{
  json: {
    // --- identidad de la traza ---
    trace_id: 'TRC-' + ahora.toISOString().slice(0, 10).replace(/-/g, '') + '-' + azar,
    timestamp: ahora.toISOString(),
    fecha: ahora.toISOString().slice(0, 10),
    t_inicio: ahora.getTime(),

    // --- entorno y fase (M9 separacion de entornos + M10 despliegue por fases) ---
    environment: cuerpo.environment || 'staging',
    fase_despliegue: Number(cuerpo.fase_despliegue ?? 2),

    // --- versiones, para poder hacer rollback y auditar hacia atras ---
    prompt_version: 'cribador-v1.2',
    rubrica_version: 'scorecard-v2.0',

    // --- datos de la postulacion ---
    candidato_id: cuerpo.candidato_id || ('CAND-' + azar),
    nombre: cuerpo.nombre || 'Sin nombre',
    email: cuerpo.email || '',
    vacante_id: cuerpo.vacante_id || 'VAC-001',
    cv_texto: cuerpo.cv_texto || '',

    // --- politica financiera (M9 lectura 2). Precios de EJEMPLO: poner los vigentes.
    presupuesto_diario_usd: 2,
    precio_input_por_millon: 0.25,
    precio_output_por_millon: 2,

    // --- politica de decision ---
    umbral_verde: 75,
    umbral_rojo: 50,
    umbral_confianza: 0.7,
    chat_id_comite: '8525478417'
  }
}];

// M9 - Lectura 1: PRINCIPIO DE MINIMIZACION DE DATOS.
// Aunque n8n sea self-hosted, lo que entra al nodo del modelo viaja a un servidor
// de terceros. La pregunta del modulo es literal: żes necesario enviar el nombre y
// el documento del cliente para esta tarea? Para decidir si cumple los must-have, no.

const j = $input.first().json;
const original = String(j.cv_texto || '');
const conteo = {};
let seguro = original;

// Reglas conservadoras a proposito: enmascarar de mas arruina la evaluacion.
// Las fechas y las metricas del CV son EVIDENCIA y tienen que llegar intactas.
const reglas = [
  ['EMAIL', /[\w.+-]+@[\w-]+\.[\w.-]+/g],
  ['TELEFONO', /\+\d[\d\s().-]{7,}\d/g],
  ['TELEFONO', /(?:tel|telefono|cel|celular|whatsapp)\s*:?\s*[\d\s().+-]{7,}/gi],
  ['DOCUMENTO', /\b\d{1,2}\.\d{3}\.\d{3}\b/g]
];

for (const [etiqueta, rx] of reglas) {
  seguro = seguro.replace(rx, () => {
    conteo[etiqueta] = (conteo[etiqueta] || 0) + 1;
    return '[' + etiqueta + '_' + conteo[etiqueta] + ']';
  });
}

const resumen = Object.keys(conteo).length
  ? Object.entries(conteo).map(([k, v]) => k + ' x' + v).join(', ')
  : 'sin PII detectada en el cuerpo del CV';

// El nombre real y el email NO se le pasan a los agentes: viajan por afuera del LLM,
// dentro de n8n, y se vuelven a unir recien en el mail al comite.
return [{
  json: {
    ...j,
    cv_seguro: seguro,
    alias: j.candidato_id,
    pii_enmascarada: resumen,
    caracteres_cv: original.length
  }
}];

// M9 - Lectura 1: DEFENSA CONTRA PROMPT INJECTION.
// El modulo propone "una capa de pre-procesamiento que analice el mensaje del usuario
// antes de pasarlo al agente principal". Aca esa capa es deterministica y gratis:
// una lista de patrones. No reemplaza al control dentro del System Prompt de cada
// worker, lo complementa. Defensa en profundidad.

const j = $input.first().json;
const texto = String(j.cv_seguro || '');

const patrones = [
  ['orden_de_ignorar',    /(ignor[aá]|olvid[aá]|descart[aá])\s+(todas\s+)?(las\s+|tus\s+)?(instrucciones|reglas|indicaciones)/i],
  ['orden_en_ingles',     /(ignore|disregard|forget)\s+(all\s+)?(previous\s+|above\s+)?(instructions?|rules?|prompts?)/i],
  ['cambio_de_rol',       /(you are now|a partir de ahora sos|actu[aá] como si fueras|nuevo rol)/i],
  ['pedido_de_puntaje',   /(asign|dale|otorg|pon)\w*\s+(le\s+)?(un\s+)?(puntaje|score|100|m[aá]xim)/i],
  ['pedido_de_veredicto', /(recomend|marc|devolv|devuelv)\w*\s+.{0,25}(elegible|contratar|apto|aprobado)/i],
  ['fuga_de_prompt',      /(system\s*prompt|revel[aá]\s+tus\s+instrucciones|mostr[aá]\s+tu\s+prompt)/i]
];

const hallados = [];
for (const [nombre, rx] of patrones) {
  if (rx.test(texto)) hallados.push(nombre);
}

return [{
  json: {
    ...j,
    injection_detectada: hallados.length > 0,
    patrones_detectados: hallados.join(', ') || 'ninguno'
  }
}];

// M9 - Lectura 2: GUARDRAIL FINANCIERO.
// El caso del modulo: un bot que ante cada saludo recorria la base entera y quemo
// 200 USD en 48 horas. Nadie lo vio hasta que llego la factura. Este nodo suma lo
// gastado HOY leyendo el propio log de auditoria y decide si se sigue o se frena.
// El modulo lo dice sin vueltas: los guardrails financieros son medidas de
// seguridad operativa, no de ahorro.

const cfg = $('Guardia de prompt injection').first().json;

// Si la tabla todavia no tiene filas de hoy, el nodo anterior devuelve un item vacio.
const filas = $input.all()
  .map(i => i.json)
  .filter(r => r && r.costo_usd !== undefined && r.costo_usd !== null);

const gasto_hoy = Number(filas.reduce((a, r) => a + Number(r.costo_usd || 0), 0).toFixed(6));
const presupuesto = Number(cfg.presupuesto_diario_usd || 2);
const consumido = presupuesto > 0 ? gasto_hoy / presupuesto : 0;

return [{
  json: {
    ...cfg,
    gasto_hoy,
    ejecuciones_hoy: filas.length,
    porcentaje_presupuesto: Math.round(consumido * 1000) / 10,
    presupuesto_ok: gasto_hoy < presupuesto,
    // Alerta de burn rate: no espera a que se agote, avisa al 80%.
    alerta_burn_rate: consumido >= 0.8
  }
}];

// M9 - Lecturas 2 y 3: acá se juntan la INSTRUMENTACION FINANCIERA y el LOG ESTRUCTURADO.
// Una sola fila por ejecucion, con los campos que el modulo declara obligatorios:
// timestamp, correlationId, nodeName, agentThought, environment, systemPromptSnapshot,
// toolOutput y confidenceScore.

// Esta funcion es la clave del nodo: al log llegan SEIS ramas distintas y no todas
// pasaron por los agentes. Leer un nodo que no se ejecuto tira error, asi que se
// consulta con red.
function leer(nombre) {
  try { return $(nombre).first().json; } catch (e) { return null; }
}

const base    = leer('Gobernanza: abrir traza') || {};
const seguro  = leer('Guardia de prompt injection') || {};
const cribado = leer('Worker: Cribado de Elegibilidad');
const score   = leer('Worker: Scorecard de Match');
const actual  = $input.first().json;

// --- COSTO (M9 lectura 2) ---
// Estimacion por 4 caracteres = 1 token. Es una aproximacion y se declara como tal
// en la columna metodo_costo: el modulo pide presupuestar, no adivinar en silencio.
const tokens_in  = Number(cribado?.tokens_in  || 0) + Number(score?.tokens_in  || 0);
const tokens_out = Number(cribado?.tokens_out || 0) + Number(score?.tokens_out || 0);
const pIn  = Number(base.precio_input_por_millon  ?? 0.25);
const pOut = Number(base.precio_output_por_millon ?? 2);
const costo_usd = Number(((tokens_in / 1e6) * pIn + (tokens_out / 1e6) * pOut).toFixed(6));

// Escenario: el modulo pide modelar tres. Aca se registra cual ocurrio de verdad,
// que es lo que permite calcular el costo promedio real en vez de multiplicar el peor caso.
const llamadas = (cribado ? 1 : 0) + (score ? 1 : 0);
const escenario = llamadas === 0 ? 'sin_inferencia' : (llamadas === 1 ? 'cold_run' : 'standard_loop');

// --- NIVEL DE AUTONOMIA (M10 lectura 3) ---
const semaforo = actual.semaforo || 'DESCONOCIDO';
const confianza = Number(score?.confianza ?? cribado?.confianza ?? 0);
const fase = Number(base.fase_despliegue ?? 2);
const umbral = Number(base.umbral_confianza ?? 0.7);

let nivel_autonomia;
if (['BLOQUEADO', 'DIFERIDO'].includes(semaforo)) {
  nivel_autonomia = 'CERRADO';                       // se corto antes; solo queda registrarlo
} else if (fase === 0) {
  nivel_autonomia = 'SOMBRA';                        // Fase 0: propone y no ejecuta nada
} else if (fase >= 3 && confianza >= umbral && ['VERDE', 'NO_ELEGIBLE'].includes(semaforo)) {
  nivel_autonomia = 'AUTONOMO';                      // Fase 3: opera dentro de guardrails
} else {
  nivel_autonomia = 'APROBACION_HUMANA';             // Fases 1 y 2, o confianza baja, o zona gris
}

// --- CADENA DE PENSAMIENTO (agentThought del M9) ---
const pensamiento = [
  cribado ? 'CRIBADO: ' + cribado.razonamiento : null,
  score   ? 'SCORECARD: ' + score.razonamiento : null
].filter(Boolean).join(' || ')
  || 'Sin inferencia: la ejecucion se detuvo antes de llamar a ningun modelo.';

return [{
  json: {
    trace_id: base.trace_id,
    fecha: base.fecha,
    timestamp: new Date().toISOString(),
    environment: base.environment,
    fase_despliegue: fase,
    nivel_autonomia,
    candidato_id: base.candidato_id,
    vacante_id: base.vacante_id,
    agente: 'Comite de Seleccion (manager + 2 workers)',
    prompt_version: base.prompt_version,
    rubrica_version: base.rubrica_version,
    elegible: cribado ? cribado.elegible === true : false,
    match_score: Number(score?.match_score ?? actual.match_score ?? 0),
    semaforo,
    confianza,
    agent_thought: String(pensamiento).slice(0, 1800),
    evidencia: String(score?.desglose || cribado?.must_have_detalle || 'sin evidencia registrada').slice(0, 1800),
    tokens_in,
    tokens_out,
    costo_usd,
    metodo_costo: 'estimacion_chars_4',
    escenario,
    latencia_ms: Date.now() - Number(base.t_inicio || Date.now()),
    pii_enmascarada: seguro.pii_enmascarada || 'no evaluada',
    injection_detectada: seguro.injection_detectada === true,
    ruta_tomada: semaforo,
    accion: actual.accion || 'sin accion registrada',
    decidido_por: 'agente'
  }
}];

